def nqueen_count(n):
    columns = []
    def place(row):
        if row == n:
            return 1
        answer = 0
        for col in range(n):
            allowed = True
            for r in range(row):
                c = columns[r]
                if col == c or abs(col-c) == row-r:
                    allowed = False
                    break
            if allowed:
                columns.append(col)
                answer += place(row+1)
                columns.pop()
        return answer
    return place(0)

