def satisfiable_3cnf(n, clauses):
    for mask in range(1 << n):
        satisfied = True
        for clause in clauses:
            clause_ok = False
            for literal in clause:
                value = (mask >> (abs(literal)-1)) & 1
                if literal < 0: value = 1-value
                if value: clause_ok = True
            if not clause_ok:
                satisfied = False
                break
        if satisfied: return 1
    return 0

