def greedy_set_cover(n, sets):
    remaining = (1 << n)-1
    count = 0
    while remaining:
        best, gain = 0, 0
        for mask in sets:
            added = (mask & remaining).bit_count()
            if added > gain:
                best, gain = mask, added
        if gain == 0: return -1
        remaining &= ~best
        count += 1
    return count

