    int remaining=(1<<n)-1, count=0;
    while (remaining) {
        int best=0, gain=0;
        for (int i=0; i<m; ++i) {
            int added=count_bits(sets[i]&remaining);
            if (added>gain) {best=sets[i]; gain=added;}
        }
        if (!gain) return -1;
        remaining&=~best; ++count;
    } return count;
}

